public enum ClassListFlags
{
    None = 0,
    /// <summary>ASN.1 named bit unmarked(0).</summary>
    Unmarked = 1 << 0,
    /// <summary>ASN.1 named bit unclassified(1).</summary>
    Unclassified = 1 << 1,
    /// <summary>ASN.1 named bit restricted(2).</summary>
    Restricted = 1 << 2,
    /// <summary>ASN.1 named bit confidential(3).</summary>
    Confidential = 1 << 3,
    /// <summary>ASN.1 named bit secret(4).</summary>
    Secret = 1 << 4,
    /// <summary>ASN.1 named bit topSecret(5).</summary>
    TopSecret = 1 << 5
}

public sealed class ClassList
{
    public Asn1BitString Value { get; set; }

    public ClassListFlags Flags
    {
        get => ToFlags(Value);
        set => Value = FromFlags(value);
    }

    public static ClassListFlags ToFlags(Asn1BitString bits)
    {
        var flags = ClassListFlags.None;
        if (bits.BitLength > 0 && bits[0]) flags |= ClassListFlags.Unmarked;
        if (bits.BitLength > 1 && bits[1]) flags |= ClassListFlags.Unclassified;
        if (bits.BitLength > 2 && bits[2]) flags |= ClassListFlags.Restricted;
        if (bits.BitLength > 3 && bits[3]) flags |= ClassListFlags.Confidential;
        if (bits.BitLength > 4 && bits[4]) flags |= ClassListFlags.Secret;
        if (bits.BitLength > 5 && bits[5]) flags |= ClassListFlags.TopSecret;
        return flags;
    }

    public static Asn1BitString FromFlags(ClassListFlags flags)
    {
        var bits = new bool[6];
        if ((flags & ClassListFlags.Unmarked) != 0) bits[0] = true;
        if ((flags & ClassListFlags.Unclassified) != 0) bits[1] = true;
        if ((flags & ClassListFlags.Restricted) != 0) bits[2] = true;
        if ((flags & ClassListFlags.Confidential) != 0) bits[3] = true;
        if ((flags & ClassListFlags.Secret) != 0) bits[4] = true;
        if ((flags & ClassListFlags.TopSecret) != 0) bits[5] = true;
        var length = bits.Length;
        while (length > 0 && !bits[length - 1])
        {
            length--;
        }
        return Asn1BitString.FromBits(bits.AsSpan(0, length));
    }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        writer.WriteBitString(tag, Value);
    }

    public static ClassList Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static ClassList Decode(Asn1Reader reader, Asn1Tag tag)
    {
        return new ClassList { Value = reader.ReadBitString(tag) };
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.BitString;
}

